import{_ as i,c as s,o as l,a3 as t}from"./chunks/framework.CoV49S2T.js";const k=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md","lastUpdated":1786612388000}'),e={name:"ja/guide/troubleshooting.md"};function o(r,a,n,h,p,d){return l(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><p>このページは、macOS 上の ClipboardxAI でよくある問題とその解決方法をまとめたものです。</p><h2 id="アプリが起動しない、または起動時にクラッシュする" tabindex="-1">アプリが起動しない、または起動時にクラッシュする <a class="header-anchor" href="#アプリが起動しない、または起動時にクラッシュする" aria-label="Permalink to &quot;アプリが起動しない、または起動時にクラッシュする&quot;">​</a></h2><ol><li>macOS のバージョンが最小要件（macOS 14 Sonoma 以上）を満たしているか確認してください。</li><li>アプリを終了して再起動してください。</li><li>Mac を再起動してください。</li><li><s>GitHub Releases からダウンロードした場合は、最新または公証済みのビルドをお試しください。</s></li><li>問題が続く場合は、ログ（下記）を収集して issue を作成してください。</li></ol><h2 id="クリップボード履歴にコピーが記録されない" tabindex="-1">クリップボード履歴にコピーが記録されない <a class="header-anchor" href="#クリップボード履歴にコピーが記録されない" aria-label="Permalink to &quot;クリップボード履歴にコピーが記録されない&quot;">​</a></h2><p>症状: 新しいコピーが履歴パネルに表示されない。</p><p>チェックリスト：</p><ol><li>アプリが動作しており、メニューバーのアイコンが表示されていることを確認してください。</li><li><strong>Clipboard monitoring（クリップボード監視）</strong> が <strong>設定 → プライバシー / 一般</strong> で有効になっていることを確認してください。</li><li>アプリはバックグラウンドでペーストボードを読み取るために該当の macOS 権限が必要です — <a href="/ja/guide/permissions.html">権限</a>を参照してください。</li><li>一部のアプリ（パスワードマネージャーやセキュア入力フィールド）は意図的にクリップボードへのアクセスをブロックします。これは仕様です。</li></ol><h2 id="クラウド-ai-アクションが結果を返さない" tabindex="-1">クラウド AI アクションが結果を返さない <a class="header-anchor" href="#クラウド-ai-アクションが結果を返さない" aria-label="Permalink to &quot;クラウド AI アクションが結果を返さない&quot;">​</a></h2><p>症状: AI アクションが失敗、フリーズ、または設定エラーを表示する。</p><p>チェックリスト：</p><ol><li><strong>設定 → AI</strong> を開き、プロバイダーが選択され、キーが入力されていることを確認してください。</li><li>そのキーがプロバイダーに対して有効で、クォータ/クレジットがあることを確認してください。</li><li>ネットワーク接続を確認してください — クラウド AI にはインターネット接続が必要です。</li><li>選択したモデル名がプロバイダーに対して正しいことを確認してください。</li><li>AI ツールウィンドウに設定バナーがまだ表示される場合、キーが Keychain に保存されていません。再度入力してください。</li></ol><h2 id="マーケットプレイスのインストールでアクションが追加されない" tabindex="-1">マーケットプレイスのインストールでアクションが追加されない <a class="header-anchor" href="#マーケットプレイスのインストールでアクションが追加されない" aria-label="Permalink to &quot;マーケットプレイスのインストールでアクションが追加されない&quot;">​</a></h2><p>症状: <strong>Install</strong> をクリックしても何も起きない、あるいはアプリが開かない。</p><p>チェックリスト：</p><ol><li>ディープリンク <code>clipboardxai://install?action=&lt;id&gt;</code> はインストール済みのアプリで処理される必要があります — ClipboardxAI がインストールされ、動作していることを確認してください。</li><li>ブラウザーがディープリンクをブロックする場合は、リンクをコピーして手動で開くか、アプリ内の <strong>Marketplace</strong> タブからインストールしてください。</li><li>そのアクション ID がマーケットプレイスにまだ公開されているか確認してください。</li></ol><h2 id="アプリのリセット" tabindex="-1">アプリのリセット <a class="header-anchor" href="#アプリのリセット" aria-label="Permalink to &quot;アプリのリセット&quot;">​</a></h2><p>設定をリセットし、ローカルデータを消去するには：</p><ol><li>ClipboardxAI を終了します。</li><li>コンテナを削除します（これにより履歴と設定が削除されます）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><ol start="3"><li>アプリを再度開き、再設定を行います。Keychain 内の API key は必要に応じて <strong>Keychain Access</strong> で別途削除してください。</li></ol><h2 id="デバッグログの収集方法" tabindex="-1">デバッグログの収集方法 <a class="header-anchor" href="#デバッグログの収集方法" aria-label="Permalink to &quot;デバッグログの収集方法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 共有用にログをデスクトップにコピー</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard/Data/Library/Logs/Clipboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AI/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>その後、<a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub</a> で issue を作成し、ログを添付してください。</p><h2 id="問題を報告する" tabindex="-1">問題を報告する <a class="header-anchor" href="#問題を報告する" aria-label="Permalink to &quot;問題を報告する&quot;">​</a></h2><p>issue を作成する際は、以下を含めてください。</p><ul><li>macOS のバージョン（Apple メニュー → この Mac について）</li><li>ClipboardxAI のバージョン（アプリメニュー → バージョン情報）</li><li>再現手順</li><li>ログ（上記参照）</li></ul><p>これにより、メンテナーが問題を特定して解決しやすくなります。</p>`,28)])])}const g=i(e,[["render",o]]);export{k as __pageData,g as default};
